'use client'

import { useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'
import {
  resolveFrameSource,
  SequenceDemandController,
  type FrameSource,
  type SequenceOptions,
} from '@/registry/lib/image-sequence/runtime'

export type { FrameSource }
export type ImageSequenceProps = Omit<SequenceOptions, 'onFrame'> & {
  sequenceId: string
  poster: FrameSource
  alt: string
  className?: string
  playing?: boolean
  resetOnPause?: boolean
  enabled?: boolean
  target?: number
  pixelated?: boolean
  onFrame?: (index: number) => void
}

/** A standalone native-image player. Change sequenceId when replacing sources. */
export function ImageSequence({
  sequenceId,
  poster,
  alt,
  className,
  playing = true,
  resetOnPause = false,
  enabled = true,
  target,
  pixelated = false,
  onFrame,
  onComplete,
  frameCount,
  source,
  mode = 'autoplay',
  frameDuration = 1000 / 24,
  loop = true,
  loopStart,
  loopEnd,
  initialFrame,
  loadInitial = false,
  priority = 'hybrid',
  ahead = 7,
  behind = 3,
}: ImageSequenceProps) {
  const rootRef = useRef<HTMLSpanElement>(null)
  const imageRef = useRef<HTMLImageElement>(null)
  const syncRef = useRef<(() => void) | null>(null)
  const surfaceLease = useRef<(() => void) | undefined>(undefined)
  const openingSurface = useRef<{
    key: string
    src: string
    retain: () => () => void
    release: () => void
  } | null>(null)
  // Opt-in hover previews start a fresh controller when resumed.
  const restart = resetOnPause ? playing : null
  const latest = useRef({
    source,
    poster,
    playing,
    resetOnPause,
    enabled,
    onFrame,
    onComplete,
    target,
  })
  // React owns the SSR poster once; the effect owns src/srcset afterwards. Parent
  // renders must never overwrite a decoded surface with an undecoded candidate.
  const [firstPoster] = useState(() =>
    typeof poster === 'string' ? { src: poster } : poster
  )

  useEffect(() => {
    latest.current = {
      source,
      poster,
      playing,
      resetOnPause,
      enabled,
      onFrame,
      onComplete,
      target,
    }
    syncRef.current?.()
  })

  useEffect(() => {
    const root = rootRef.current
    const image = imageRef.current
    if (!root || !image) return
    const runKey = JSON.stringify([
      sequenceId,
      initialFrame,
      loopStart,
      loopEnd,
      frameCount,
      resetOnPause,
    ])
    if (openingSurface.current?.key !== runKey) {
      openingSurface.current?.release()
      openingSurface.current = null
    }
    const motion = matchMedia('(prefers-reduced-motion: reduce)')
    let nearby = false
    let visible = false
    let disposed = false
    let raf: number | undefined
    let lastTarget: number | undefined
    let lastTime: number | undefined
    let pixelWidth = Math.max(
      1,
      Math.ceil(image.getBoundingClientRect().width * devicePixelRatio)
    )
    const controller = new SequenceDemandController({
      frameCount,
      mode,
      frameDuration,
      loop,
      loopStart,
      loopEnd,
      initialFrame,
      loadInitial,
      priority,
      ahead,
      behind,
      source: (index) =>
        resolveFrameSource(latest.current.source(index), pixelWidth),
      onFrame: (index, frame) => {
        if (
          disposed ||
          !image.isConnected ||
          motion.matches ||
          !latest.current.enabled ||
          !latest.current.playing ||
          document.hidden
        )
          return false
        const releasePrevious = surfaceLease.current
        const releaseNext = controller.retainSurface(frame)
        image.removeAttribute('srcset')
        image.src = frame.src
        surfaceLease.current = releaseNext
        releasePrevious?.()
        if (latest.current.resetOnPause && !openingSurface.current) {
          const retain = () => controller.retainSurface(frame)
          openingSurface.current = {
            key: runKey,
            src: frame.src,
            retain,
            release: retain(),
          }
        }
        latest.current.onFrame?.(index)
        return true
      },
      onComplete: () => latest.current.onComplete?.(),
    })

    const stop = () => {
      if (raf !== undefined) cancelAnimationFrame(raf)
      raf = undefined
      lastTime = undefined
    }
    const tick = (time: number) => {
      raf = undefined
      controller.tick(lastTime === undefined ? 0 : time - lastTime)
      lastTime = time
      if (!disposed && !controller.isComplete) raf = requestAnimationFrame(tick)
    }
    const assignPoster = () => {
      const current = latest.current.poster
      const value = typeof current === 'string' ? { src: current } : current
      // Reassigning the same URL can restart the native poster request, notably
      // with browser cache disabled. Observer notifications must be idempotent.
      if ((image.getAttribute('sizes') ?? '') !== (value.sizes ?? ''))
        image.sizes = value.sizes ?? ''
      if ((image.getAttribute('srcset') ?? '') !== (value.srcSet ?? ''))
        image.srcset = value.srcSet ?? ''
      if (image.getAttribute('src') !== value.src) image.src = value.src
    }
    const restorePoster = (useOpeningFrame = false) => {
      const opening = useOpeningFrame ? openingSurface.current : null
      const releasePrevious = surfaceLease.current
      surfaceLease.current = opening?.retain()
      if (opening) {
        image.removeAttribute('srcset')
        if (image.src !== opening.src) image.src = opening.src
      } else assignPoster()
      releasePrevious?.()
      controller.restorePoster()
    }
    const sync = () => {
      const target = latest.current.target
      if (target !== undefined && target !== lastTarget) {
        lastTarget = target
        controller.queueTarget(target)
      }
      const allowed =
        !document.hidden &&
        !motion.matches &&
        latest.current.enabled &&
        latest.current.playing
      controller.setConditions(nearby && allowed, visible && allowed)
      if (visible && allowed && mode !== 'scrub' && !controller.isComplete) {
        if (raf === undefined) raf = requestAnimationFrame(tick)
      } else stop()
      if (
        motion.matches ||
        (latest.current.resetOnPause && !latest.current.playing)
      )
        restorePoster(!motion.matches)
      else if (!surfaceLease.current) assignPoster()
    }
    const resize = () => {
      const next = Math.max(
        1,
        Math.ceil(image.getBoundingClientRect().width * devicePixelRatio)
      )
      if (pixelWidth === next) return
      pixelWidth = next
      controller.resetWindow()
    }
    const visibilityObserver = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting
      sync()
    })
    const nearbyObserver = new IntersectionObserver(
      ([entry]) => {
        nearby = entry.isIntersecting
        sync()
      },
      { rootMargin: '200px' }
    )
    const sizeObserver = new ResizeObserver(resize)
    visibilityObserver.observe(root)
    nearbyObserver.observe(root)
    sizeObserver.observe(image)
    motion.addEventListener('change', sync)
    document.addEventListener('visibilitychange', sync)
    window.addEventListener('resize', resize)
    window.addEventListener('orientationchange', resize)
    syncRef.current = sync
    sync()
    return () => {
      disposed = true
      stop()
      visibilityObserver.disconnect()
      nearbyObserver.disconnect()
      sizeObserver.disconnect()
      motion.removeEventListener('change', sync)
      document.removeEventListener('visibilitychange', sync)
      window.removeEventListener('resize', resize)
      window.removeEventListener('orientationchange', resize)
      controller.dispose()
      syncRef.current = null
      // The separate surface lease survives replacement of this controller.
    }
  }, [
    restart,
    resetOnPause,
    sequenceId,
    frameCount,
    mode,
    frameDuration,
    loop,
    loopStart,
    loopEnd,
    initialFrame,
    loadInitial,
    priority,
    ahead,
    behind,
  ])

  useEffect(
    () => () => {
      surfaceLease.current?.()
      surfaceLease.current = undefined
      openingSurface.current?.release()
      openingSurface.current = null
    },
    []
  )

  const dimensions = typeof poster === 'string' ? undefined : poster
  return (
    <span
      ref={rootRef}
      data-slot="image-sequence"
      className={cn(
        'relative block **:data-[slot=sequence-image]:block **:data-[slot=sequence-image]:size-full **:data-[slot=sequence-image]:object-contain **:data-[slot=sequence-picture]:block **:data-[slot=sequence-picture]:size-full',
        pixelated &&
          '**:data-[slot=sequence-image]:[image-rendering:pixelated]',
        className
      )}
    >
      <picture data-slot="sequence-picture">
        <img
          ref={imageRef}
          data-slot="sequence-image"
          src={firstPoster.src}
          srcSet={firstPoster.srcSet}
          sizes={firstPoster.sizes}
          width={dimensions?.width}
          height={dimensions?.height}
          alt={alt}
          draggable={false}
          decoding="async"
        />
      </picture>
    </span>
  )
}

import {
  getSharedFrameTransfer,
  sourceUrl,
  type TransferDemand,
} from './transfer'

export type FrameSource =
  | string
  | {
      src: string
      srcSet?: string
      sizes?: string
      width?: number
      height?: number
      accept?: string
    }
type DecodedFrame = HTMLImageElement
type Demand = TransferDemand & { index: number }
const READY_AHEAD = 3

/** Spread first, last, and midpoint transfer requests across a frame range. */
function binaryFrameOrder(first: number, last: number): number[] {
  if (first > last) return []
  if (first === last) return [first]
  const order = [first, last]
  const ranges: [number, number][] = [[first, last]]
  for (let position = 0; position < ranges.length; position++) {
    const [start, end] = ranges[position]
    if (end - start <= 1) continue
    const middle = Math.floor((start + end) / 2)
    order.push(middle)
    ranges.push([start, middle], [middle, end])
  }
  return order
}

/** Pick the smallest responsive candidate that covers the visible image's physical pixels. */
export function resolveFrameSource(
  source: FrameSource,
  pixelWidth: number
): FrameSource {
  if (typeof source === 'string' || !source.srcSet) return source
  const candidates = source.srcSet
    .split(',')
    .flatMap((candidate) => {
      const [url, descriptor] = candidate.trim().split(/\s+/)
      const width = Number(descriptor?.match(/^(\d+)w$/)?.[1])
      return width > 0 ? [{ url, width }] : []
    })
    .sort((a, b) => a.width - b.width)
  const selected =
    candidates.find((candidate) => candidate.width >= pixelWidth) ??
    candidates.at(-1)
  return { ...source, src: selected?.url ?? source.src, srcSet: undefined }
}

function releaseFrame(frame: DecodedFrame) {
  URL.revokeObjectURL(frame.src)
  frame.removeAttribute('src')
}

async function decodeFrame(
  blob: Blob,
  signal: AbortSignal
): Promise<DecodedFrame> {
  const image = new Image()
  image.decoding = 'async'
  const src = URL.createObjectURL(blob)
  image.src = src
  let timeout: ReturnType<typeof setTimeout> | undefined
  let onAbort: (() => void) | undefined
  try {
    if (signal.aborted) throw signal.reason
    const cancelled = new Promise<never>((_, reject) => {
      onAbort = () =>
        reject(signal.reason ?? new DOMException('Cancelled', 'AbortError'))
      signal.addEventListener('abort', onAbort, { once: true })
    })
    const timedOut = new Promise<never>((_, reject) => {
      timeout = setTimeout(
        () => reject(new DOMException('Decode timeout', 'TimeoutError')),
        15_000
      )
    })
    await Promise.race([image.decode(), cancelled, timedOut])
    if (signal.aborted) throw signal.reason
    return image
  } catch (error) {
    image.removeAttribute('src')
    URL.revokeObjectURL(src)
    throw error
  } finally {
    if (timeout) clearTimeout(timeout)
    if (onAbort) signal.removeEventListener('abort', onAbort)
  }
}

/** A sequence's decoded ring and bounded decode pump. */
class LocalFrames {
  private transport = getSharedFrameTransfer()
  private frames = new Map<string, DecodedFrame>()
  private retained = new Map<DecodedFrame, number>()
  private wanted: FrameSource[] = []
  private visible?: string
  private pending = new Map<string, AbortController>()
  private readonly decodeConcurrency = 3
  private disposed = false
  private decodeFailures = new Map<string, number>()
  private retryTimers = new Map<string, ReturnType<typeof setTimeout>>()
  constructor(
    private owner: symbol,
    private source: (index: number) => FrameSource,
    private notify: (reason: 'transfer' | 'decode') => void
  ) {}
  get(source: FrameSource) {
    return this.frames.get(sourceUrl(source))
  }
  isReady(source: FrameSource) {
    return this.frames.has(sourceUrl(source))
  }
  hasBytes(source: FrameSource) {
    return Boolean(this.transport.get(source))
  }
  retain(frame: DecodedFrame) {
    this.retained.set(frame, (this.retained.get(frame) ?? 0) + 1)
    let released = false
    return () => {
      if (released) return
      released = true
      const count = (this.retained.get(frame) ?? 1) - 1
      if (count) this.retained.set(frame, count)
      else {
        this.retained.delete(frame)
        if (![...this.frames.values()].includes(frame)) releaseFrame(frame)
      }
    }
  }
  setVisible(source: FrameSource) {
    this.visible = sourceUrl(source)
    this.trim()
  }
  update(wanted: Demand[], decode: number[], active: boolean) {
    if (this.disposed) return
    this.wanted = decode.map(this.source)
    const demandUrls = new Set(this.wanted.map(sourceUrl))
    // This bounds relevant decode promises. Browser codec work abandoned after
    // cancellation may overlap briefly because HTMLImageElement.decode() has no
    // cancellable API. Current demand must not wait behind obsolete frames.
    for (const [url, controller] of this.pending)
      if (!demandUrls.has(url)) {
        controller.abort()
        this.pending.delete(url)
      }
    this.transport.update(
      this.owner,
      wanted,
      () => {
        this.pump()
        this.notify('transfer')
      },
      active
    )
    this.trim()
    this.pump()
  }
  private trim() {
    const keep = new Set(this.wanted.map(sourceUrl))
    if (this.visible) keep.add(this.visible)
    for (const url of this.decodeFailures.keys())
      if (!keep.has(url)) {
        this.decodeFailures.delete(url)
        const timer = this.retryTimers.get(url)
        if (timer) clearTimeout(timer)
        this.retryTimers.delete(url)
      }
    for (const [url, frame] of this.frames) {
      if (keep.has(url)) continue
      this.frames.delete(url)
      if (!this.retained.has(frame)) releaseFrame(frame)
    }
  }
  private pump() {
    if (this.disposed) return
    for (const next of this.wanted) {
      if (this.pending.size >= this.decodeConcurrency) break
      const url = sourceUrl(next)
      if (
        this.frames.has(url) ||
        this.retryTimers.has(url) ||
        this.pending.has(url)
      )
        continue
      const blob = this.transport.get(next)
      if (!blob) continue
      this.startDecode(url, blob)
    }
  }
  private startDecode(url: string, blob: Blob) {
    const controller = new AbortController()
    this.pending.set(url, controller)
    void decodeFrame(blob, controller.signal)
      .then(
        (frame) => {
          if (
            this.disposed ||
            controller.signal.aborted ||
            this.pending.get(url) !== controller ||
            !this.wanted.some((source) => sourceUrl(source) === url)
          ) {
            releaseFrame(frame)
            return
          }
          this.frames.set(url, frame)
          this.notify('decode')
        },
        () => {
          if (controller.signal.aborted || this.disposed) return
          const failures = (this.decodeFailures.get(url) ?? 0) + 1
          this.decodeFailures.set(url, failures)
          const delay = Math.min(500 * 2 ** Math.min(failures - 1, 6), 30_000)
          this.retryTimers.set(
            url,
            setTimeout(() => {
              this.retryTimers.delete(url)
              if (!this.disposed) this.pump()
            }, delay)
          )
        }
      )
      .finally(() => {
        if (this.pending.get(url) === controller) this.pending.delete(url)
        this.trim()
        this.pump()
      })
  }
  resize() {
    for (const controller of this.pending.values()) controller.abort()
    this.pending.clear()
    this.decodeFailures.clear()
    for (const timer of this.retryTimers.values()) clearTimeout(timer)
    this.retryTimers.clear()
    for (const frame of this.frames.values())
      if (!this.retained.has(frame)) releaseFrame(frame)
    this.frames.clear()
  }
  suspend() {
    this.wanted = []
    for (const controller of this.pending.values()) controller.abort()
    this.pending.clear()
    this.visible = undefined
    this.trim()
    this.transport.release(this.owner)
  }
  release() {
    if (this.disposed) return
    this.disposed = true
    this.resize()
    this.transport.release(this.owner)
  }
}

export type SequenceOptions = {
  frameCount: number
  source: (index: number) => FrameSource
  onFrame: (index: number, frame: DecodedFrame) => boolean | void
  onComplete?: () => void
  mode?: 'autoplay' | 'scrub'
  frameDuration?: number
  loop?: boolean
  loopStart?: number
  loopEnd?: number
  initialFrame?: number
  loadInitial?: boolean
  priority?: 'sequential' | 'hybrid'
  ahead?: number
  behind?: number
}

const integer = (value: number | undefined, fallback: number) =>
  value !== undefined && Number.isFinite(value) ? Math.floor(value) : fallback

/** Owns demand and playback; React never receives the per-frame working set. */
export class SequenceDemandController {
  private owner = Symbol('sequence')
  private frames: LocalFrames
  private current: number
  private playhead: number
  private target: number
  private direction = 1
  private elapsed = 0
  private nearby = false
  private playing = false
  private disposed = false
  private hasPresented = false
  private presentedUrl?: string
  private cycle = 0
  private presentedCycle = 0
  private queuedTarget?: number
  private targetRaf?: number
  private readonly count: number
  private readonly start: number
  private readonly end: number
  private readonly initial: number
  private readonly duration: number
  private readonly order: number[]
  private readonly hybrid: boolean
  private completed = false

  constructor(private options: SequenceOptions) {
    this.count = Math.max(0, integer(options.frameCount, 0))
    this.end = Math.max(
      0,
      Math.min(this.count - 1, integer(options.loopEnd, this.count - 1))
    )
    this.start = Math.max(0, Math.min(this.end, integer(options.loopStart, 0)))
    this.initial = Math.max(
      this.start,
      Math.min(this.end, integer(options.initialFrame, this.start))
    )
    this.current = this.playhead = this.target = this.initial
    this.duration = Math.max(
      1,
      Number.isFinite(options.frameDuration)
        ? options.frameDuration!
        : 1000 / 24
    )
    this.hybrid = options.priority !== 'sequential'
    this.order = binaryFrameOrder(this.start, this.end)
    this.frames = new LocalFrames(this.owner, options.source, (reason) => {
      if (this.disposed || !this.nearby || this.completed) return
      if (reason === 'transfer') this.refresh()
      if (options.mode === 'scrub') this.presentTarget()
      else if (!this.hasPresented && (this.playing || options.loadInitial))
        this.present(this.initial)
    })
  }

  get isComplete() {
    return this.completed
  }

  setConditions(nearby: boolean, playing: boolean) {
    if (this.disposed) return
    this.nearby = nearby
    this.playing = nearby && playing
    if (!this.playing) this.elapsed = 0
    this.refresh()
    if (nearby && this.options.mode === 'scrub') this.presentTarget()
    else if (
      nearby &&
      !this.hasPresented &&
      (this.playing || this.options.loadInitial)
    )
      this.present(this.initial)
  }

  setTarget(index: number) {
    if (this.disposed || !Number.isFinite(index)) return
    const next = Math.max(this.start, Math.min(this.end, Math.round(index)))
    if (next !== this.target) this.direction = next > this.target ? 1 : -1
    this.target = next
    this.refresh()
    this.presentTarget()
  }

  /** Coalesce scroll input and suppress presentation against an outdated target. */
  queueTarget(index: number) {
    if (this.disposed) return
    this.queuedTarget = index
    if (this.targetRaf !== undefined) return
    this.targetRaf = requestAnimationFrame(() => {
      this.targetRaf = undefined
      const target = this.queuedTarget
      this.queuedTarget = undefined
      if (target !== undefined) this.setTarget(target)
    })
  }

  tick(delta: number) {
    if (
      !this.playing ||
      this.disposed ||
      this.completed ||
      !this.count ||
      this.options.mode === 'scrub'
    )
      return
    if (!this.hasPresented) {
      this.present(this.initial)
      return
    }
    this.elapsed += Math.max(0, Number.isFinite(delta) ? delta : 0)
    if (this.hybrid) {
      const steps = Math.floor(this.elapsed / this.duration)
      if (steps) {
        this.elapsed %= this.duration
        if (this.options.loop !== false && steps > this.end - this.playhead) {
          this.cycle +=
            1 +
            Math.floor(
              (steps - (this.end - this.playhead + 1)) /
                (this.end - this.start + 1)
            )
        }
        this.playhead = this.advance(this.playhead, steps)
        this.refresh()
      }
      const candidate = this.closestReady()
      if (candidate !== undefined) this.present(candidate)
    } else if (this.elapsed >= this.duration) {
      // Hold authored time until an allowed next frame is ready.
      this.elapsed = Math.min(this.elapsed, this.duration * 2)
      this.refresh()
      const next = this.advance(this.current, 1)
      if (this.frames.isReady(this.options.source(next))) {
        this.elapsed -= this.duration
        this.playhead = next
        this.present(next)
      }
    }
  }

  resetWindow() {
    if (this.disposed) return
    this.frames.resize()
    this.refresh()
  }

  /** Poster restoration invalidates the presentation identity, not the run. */
  restorePoster() {
    this.hasPresented = false
    this.presentedUrl = undefined
  }

  retainSurface(frame: DecodedFrame) {
    return this.frames.retain(frame)
  }

  dispose() {
    this.disposed = true
    if (this.targetRaf !== undefined) cancelAnimationFrame(this.targetRaf)
    this.frames.release()
  }

  private advance(index: number, offset: number) {
    if (this.options.loop === false) return Math.min(this.end, index + offset)
    return (
      this.start + ((index - this.start + offset) % (this.end - this.start + 1))
    )
  }

  private canPresent(index: number) {
    return this.cycle > this.presentedCycle || index >= this.current
  }

  private closestReady() {
    let candidate: number | undefined
    for (const index of this.order) {
      if (
        !this.canPresent(index) ||
        !this.frames.isReady(this.options.source(index))
      )
        continue
      // One-shot completion must follow authored time all the way to the end.
      if (
        this.options.loop === false &&
        index === this.end &&
        this.playhead !== this.end
      )
        continue
      if (
        candidate === undefined ||
        Math.abs(index - this.playhead) < Math.abs(candidate - this.playhead) ||
        (Math.abs(index - this.playhead) ===
          Math.abs(candidate - this.playhead) &&
          index < candidate)
      )
        candidate = index
    }
    return candidate
  }

  private presentTarget() {
    if (
      this.options.mode !== 'scrub' ||
      !this.nearby ||
      this.queuedTarget !== undefined
    )
      return
    const direction = this.target >= this.current ? -1 : 1
    for (
      let index = this.target;
      direction === -1 ? index >= this.current : index <= this.current;
      index += direction
    ) {
      if (this.frames.isReady(this.options.source(index))) {
        this.present(index)
        return
      }
    }
  }

  private present(index: number) {
    if (this.disposed || !this.nearby || !this.count || this.completed) return
    const source = this.options.source(index)
    const url = sourceUrl(source)
    const frame = this.frames.get(source)
    if (
      !frame ||
      (this.hasPresented && index === this.current && this.presentedUrl === url)
    )
      return
    if (this.options.onFrame(index, frame) === false) return
    if (this.disposed) return
    this.current = index
    this.hasPresented = true
    this.presentedUrl = url
    this.presentedCycle = this.cycle
    this.frames.setVisible(source)
    if (
      this.options.mode !== 'scrub' &&
      this.options.loop === false &&
      index === this.end &&
      this.playhead === this.end
    ) {
      this.completed = true
      this.frames.suspend()
      this.options.onComplete?.()
      return
    }
    this.refresh()
  }

  private refresh() {
    if (this.disposed) return
    if (!this.nearby || !this.count || this.completed) {
      this.frames.suspend()
      return
    }
    const wanted: Demand[] = []
    const added = new Set<number>()
    const add = (index: number, priority: number) => {
      if (added.has(index)) return
      added.add(index)
      wanted.push({ index, source: this.options.source(index), priority })
    }
    let decode: number[]
    if (this.options.mode === 'scrub') {
      add(this.target, 0)
      if (this.playing) {
        const ahead = Math.min(
          this.count,
          Math.max(0, integer(this.options.ahead, 7))
        )
        const behind = Math.min(
          this.count,
          Math.max(0, integer(this.options.behind, 3))
        )
        for (let i = 1; i <= ahead; i++) {
          const index = this.target + i * this.direction
          if (index >= this.start && index <= this.end) add(index, i)
        }
        for (let i = 1; i <= behind; i++) {
          const index = this.target - i * this.direction
          if (index >= this.start && index <= this.end) add(index, ahead + i)
        }
      }
      decode = wanted
        .filter((item) => item.index !== this.current)
        .slice(0, 3)
        .map((item) => item.index)
      if (added.has(this.current)) decode.unshift(this.current)
    } else if (!this.playing) {
      add(this.hasPresented ? this.current : this.initial, 0)
      add(this.advance(this.playhead, 1), 1)
      decode =
        this.options.loadInitial && !this.hasPresented ? [this.initial] : []
    } else if (!this.hasPresented) {
      add(this.initial, 0)
      add(this.end, 1)
      if (this.hybrid) this.order.forEach((index, rank) => add(index, rank + 2))
      decode = [this.initial]
    } else if (this.hybrid) {
      add(this.playhead, 0)
      for (let offset = 1; offset <= READY_AHEAD; offset++)
        add(this.advance(this.playhead, offset), 1)
      this.order.forEach((index, rank) => add(index, rank + 2))
      decode = wanted
        .filter((item) => item.index !== this.current)
        .slice(0, READY_AHEAD)
        .map((item) => item.index)
      if (
        !decode.some((index) =>
          this.frames.hasBytes(this.options.source(index))
        )
      ) {
        const fallback = wanted
          .filter(
            (item) =>
              item.index !== this.current &&
              this.canPresent(item.index) &&
              this.frames.hasBytes(item.source)
          )
          .sort(
            (a, b) =>
              Math.abs(a.index - this.playhead) -
              Math.abs(b.index - this.playhead)
          )[0]
        if (fallback)
          decode = [
            fallback.index,
            ...decode.filter((index) => index !== fallback.index),
          ].slice(0, READY_AHEAD)
      }
      if (this.playhead === this.current) decode.unshift(this.current)
    } else {
      for (let offset = 1; offset <= READY_AHEAD; offset++)
        add(this.advance(this.current, offset), offset)
      decode = wanted.map((item) => item.index)
    }
    this.frames.update(wanted, decode, this.playing)
  }
}

import type { FrameSource } from './runtime'

export type TransferDemand = { source: FrameSource; priority: number }
type Owner = { wanted: TransferDemand[]; notify: () => void; active: boolean }
type Entry = {
  url: string
  accept?: string
  state: 'queued' | 'pending' | 'failed' | 'ready'
  controller?: AbortController
  failures: number
  retryTimer?: ReturnType<typeof setTimeout>
  retireTimer?: ReturnType<typeof setTimeout>
  contentionTimer?: ReturnType<typeof setTimeout>
  timedOut?: boolean
  preempted?: boolean
  reclaiming?: boolean
  preemptTimer?: ReturnType<typeof setTimeout>
}
const DEFAULT_ENCODED_FRAME_BUDGET = 16 * 1024 * 1024
const PENDING_FRAME_GRACE_MS = 1_000
const CONTENDED_FRAME_IDLE_MS = 15_000
export const sourceUrl = (source: FrameSource) =>
  typeof source === 'string' ? source : source.src

class OversizedFrameError extends Error {
  constructor() {
    super('Frame exceeds encoded byte budget')
    this.name = 'OversizedFrameError'
  }
}

class FrameHttpError extends Error {
  readonly retryable: boolean
  constructor(status: number) {
    super(`Frame request failed: ${status}`)
    this.retryable = status === 408 || status === 429 || status >= 500
  }
}

/** Compressed responses survive local decoded-frame eviction. */
class EncodedFrameCache {
  private entries = new Map<string, Blob>()
  private bytes = 0
  has(url: string) {
    return this.entries.has(url)
  }
  get(url: string) {
    const blob = this.entries.get(url)
    if (!blob) return undefined
    this.entries.delete(url)
    this.entries.set(url, blob)
    return blob
  }
  put(url: string, blob: Blob) {
    const previous = this.entries.get(url)
    if (previous) {
      this.bytes -= previous.size
      this.entries.delete(url)
    }
    if (blob.size > DEFAULT_ENCODED_FRAME_BUDGET) return
    this.entries.set(url, blob)
    this.bytes += blob.size
    while (this.bytes > DEFAULT_ENCODED_FRAME_BUDGET) {
      const oldest = this.entries.keys().next().value
      if (oldest === undefined) break
      this.bytes -= this.entries.get(oldest)!.size
      this.entries.delete(oldest)
    }
  }
}

/** Shared admission and deduplication. Owns encoded bytes, never decoded images. */
class FrameTransfer {
  private entries = new Map<string, Entry>()
  private owners = new Map<symbol, Owner>()
  private active = 0
  private reclaiming = 0
  private lastOwner?: symbol
  private encoded = new EncodedFrameCache()
  private concurrency = 8
  private async load(
    url: string,
    signal: AbortSignal,
    accept?: string,
    onBytes?: () => void
  ) {
    const response = await fetch(url, {
      signal,
      priority: 'low',
      ...(accept ? { headers: { Accept: accept } } : {}),
    })
    if (!response.ok) {
      void response.body?.cancel().catch(() => {})
      throw new FrameHttpError(response.status)
    }
    const type = response.headers.get('content-type') ?? ''
    if (!response.body) return new Blob([], { type })
    const reader = response.body.getReader()
    const chunks: Uint8Array<ArrayBuffer>[] = []
    let bytes = 0
    try {
      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        if (value.byteLength === 0) continue
        if (value.byteLength > DEFAULT_ENCODED_FRAME_BUDGET - bytes) {
          void reader.cancel().catch(() => {})
          throw new OversizedFrameError()
        }
        bytes += value.byteLength
        // Stream producers may reuse the buffer before the Blob is assembled.
        chunks.push(new Uint8Array(value))
        onBytes?.()
      }
    } finally {
      reader.releaseLock()
    }
    return new Blob(chunks, { type })
  }
  get(source: FrameSource) {
    return this.encoded.get(sourceUrl(source))
  }
  update(
    owner: symbol,
    wanted: TransferDemand[],
    notify: () => void,
    active = true
  ) {
    this.owners.set(owner, { wanted, notify, active })
    for (const item of wanted) {
      const entry = this.entries.get(sourceUrl(item.source))
      if (
        entry?.state === 'ready' &&
        !this.encoded.has(entry.url) &&
        item.priority <= 1
      )
        entry.state = 'queued'
    }
    this.reconcile()
  }
  release(owner: symbol) {
    this.owners.delete(owner)
    this.reconcile()
  }
  private desired() {
    const wanted = new Map<string, string | undefined>()
    for (const owner of this.owners.values()) {
      for (const item of owner.wanted) {
        const url = sourceUrl(item.source)
        const accept =
          typeof item.source === 'string' ? undefined : item.source.accept
        if (wanted.has(url) && wanted.get(url) !== accept)
          throw new Error(`Conflicting Accept headers for frame ${url}`)
        wanted.set(url, accept)
      }
    }
    return wanted
  }
  private visibleUrls() {
    const wanted = new Set<string>()
    for (const owner of this.owners.values())
      if (owner.active)
        for (const item of owner.wanted) wanted.add(sourceUrl(item.source))
    return wanted
  }
  private queue() {
    const seen = new Set<string>()
    const owners = [...this.owners.entries()]
    const previous = owners.findIndex(([id]) => id === this.lastOwner)
    const rotated = [
      ...owners.slice(previous + 1),
      ...owners.slice(0, previous + 1),
    ]
    const queue: { url: string; owner: symbol }[] = []
    // Rotate after every admission, including when only one slot becomes free.
    // Rebuilding a fixed owner order would starve later owners on rolling requests.
    for (const active of [true, false]) {
      const lanes = rotated
        .filter(([, owner]) => owner.active === active)
        .map(([id, owner]) => ({
          id,
          urls: [...owner.wanted]
            .sort((a, b) => a.priority - b.priority)
            .map((item) => sourceUrl(item.source)),
        }))
      while (lanes.some((lane) => lane.urls.length)) {
        for (const lane of lanes) {
          let url = lane.urls.shift()
          while (
            url &&
            (seen.has(url) || this.entries.get(url)?.state !== 'queued')
          )
            url = lane.urls.shift()
          if (url) {
            seen.add(url)
            queue.push({ url, owner: lane.id })
          }
        }
      }
    }
    return queue
  }
  private reconcile() {
    const wanted = this.desired()
    for (const [url, entry] of this.entries) {
      if (!wanted.has(url)) {
        if (entry.state === 'pending') this.retire(entry)
        else {
          if (entry.retryTimer) clearTimeout(entry.retryTimer)
          this.clearContentionTimer(entry)
          this.entries.delete(url)
        }
      } else if (entry.retireTimer) {
        clearTimeout(entry.retireTimer)
        entry.retireTimer = undefined
      }
    }
    for (const [url, accept] of wanted)
      if (!this.encoded.has(url) && !this.entries.has(url))
        this.entries.set(url, { url, accept, state: 'queued', failures: 0 })
    const queue = this.queue()
    let slotsNeeded = Math.max(
      0,
      Math.min(
        queue.length,
        this.active - this.reclaiming + queue.length - this.concurrency
      )
    )
    for (const [url, entry] of this.entries) {
      if (!slotsNeeded || !entry.retireTimer) continue
      clearTimeout(entry.retireTimer)
      entry.retireTimer = undefined
      entry.controller?.abort()
      entry.reclaiming = true
      this.reclaiming++

      this.entries.delete(url)
      slotsNeeded--
    }
    // A newly visible owner must not wait behind already admitted nearby work.
    const visibleUrls = this.visibleUrls()
    const visibleQueued = queue.filter((item) => visibleUrls.has(item.url))
    let visibleSlotsNeeded = Math.max(
      0,
      Math.min(
        visibleQueued.length,
        this.active - this.reclaiming + visibleQueued.length - this.concurrency
      )
    )
    for (const entry of this.entries.values()) {
      if (!visibleSlotsNeeded) break
      if (
        entry.state !== 'pending' ||
        !wanted.has(entry.url) ||
        visibleUrls.has(entry.url) ||
        entry.controller?.signal.aborted
      )
        continue
      // Keep the entry pending until its aborted fetch settles, then requeue it.
      // This preserves deduplication and prevents it from racing the visible URL.
      if (!entry.preemptTimer)
        entry.preemptTimer = setTimeout(() => {
          entry.preemptTimer = undefined
          if (
            entry.state !== 'pending' ||
            entry.controller?.signal.aborted ||
            this.visibleUrls().has(entry.url) ||
            !this.queue().some((item) => this.visibleUrls().has(item.url))
          )
            return
          entry.preempted = true
          entry.controller?.abort()
          entry.reclaiming = true
          this.reclaiming++
        }, PENDING_FRAME_GRACE_MS)
      visibleSlotsNeeded--
    }
    for (const { url, owner } of queue) {
      if (this.active >= this.concurrency) break
      const entry = this.entries.get(url)
      if (!entry || entry.state !== 'queued') continue
      const controller = new AbortController()
      entry.controller = controller
      entry.state = 'pending'
      entry.timedOut = false
      this.lastOwner = owner
      this.active++
      void this.load(url, controller.signal, entry.accept, () => {
        if (entry.controller !== controller || controller.signal.aborted) return
        if (entry.contentionTimer) this.armContentionTimer(entry)
      })
        .then(
          (blob) => {
            if (controller.signal.aborted || this.entries.get(url) !== entry)
              return
            this.encoded.put(url, blob)
            entry.state = 'ready'

            for (const owner of this.owners.values()) owner.notify()
          },
          (error) => {
            if (
              (controller.signal.aborted && !entry.timedOut) ||
              this.entries.get(url) !== entry
            )
              return
            this.fail(entry, error)
          }
        )
        .finally(() => {
          this.clearContentionTimer(entry)
          if (entry.preemptTimer) clearTimeout(entry.preemptTimer)
          entry.preemptTimer = undefined
          this.active--
          if (entry.reclaiming) {
            this.reclaiming--
            entry.reclaiming = false
          }
          if (
            entry.timedOut &&
            entry.state === 'pending' &&
            this.entries.get(url) === entry
          )
            this.fail(entry, controller.signal.reason)
          entry.controller = undefined
          if (entry.retireTimer) clearTimeout(entry.retireTimer)
          entry.retireTimer = undefined
          if (entry.preempted) {
            entry.preempted = false
            if (this.entries.get(url) === entry) {
              if (this.desired().has(url)) entry.state = 'queued'
              else this.entries.delete(url)
            }
          }
          this.reconcile()
        })
    }
    this.syncContentionTimers()
  }
  private clearContentionTimer(entry: Entry) {
    if (entry.contentionTimer) clearTimeout(entry.contentionTimer)
    entry.contentionTimer = undefined
  }
  private hasQueuedFrames() {
    for (const entry of this.entries.values())
      if (entry.state === 'queued') return true
    return false
  }
  private armContentionTimer(entry: Entry) {
    this.clearContentionTimer(entry)
    const controller = entry.controller
    if (!controller) return
    entry.contentionTimer = setTimeout(() => {
      entry.contentionTimer = undefined
      if (
        this.entries.get(entry.url) !== entry ||
        entry.state !== 'pending' ||
        entry.controller !== controller ||
        controller.signal.aborted ||
        this.active - this.reclaiming < this.concurrency ||
        !this.hasQueuedFrames()
      )
        return
      entry.timedOut = true
      entry.reclaiming = true
      this.reclaiming++
      controller.abort(
        new DOMException('Contended frame stalled', 'TimeoutError')
      )
      this.syncContentionTimers()
    }, CONTENDED_FRAME_IDLE_MS)
  }
  private syncContentionTimers() {
    const queued = this.hasQueuedFrames()
    const contended =
      queued && this.active - this.reclaiming >= this.concurrency
    for (const entry of this.entries.values()) {
      if (
        !queued ||
        entry.state !== 'pending' ||
        entry.retireTimer ||
        !entry.controller ||
        entry.controller.signal.aborted
      )
        this.clearContentionTimer(entry)
      else if (contended) {
        if (!entry.contentionTimer) this.armContentionTimer(entry)
      } else this.clearContentionTimer(entry)
    }
  }
  private retire(entry: Entry) {
    if (entry.retireTimer) return
    this.clearContentionTimer(entry)
    if (!entry.controller) {
      this.entries.delete(entry.url)
      return
    }
    entry.retireTimer = setTimeout(() => {
      entry.retireTimer = undefined
      if (
        this.entries.get(entry.url) !== entry ||
        this.desired().has(entry.url) ||
        entry.state !== 'pending'
      )
        return
      entry.controller?.abort()
      entry.reclaiming = true
      this.reclaiming++

      this.entries.delete(entry.url)
    }, PENDING_FRAME_GRACE_MS)
  }
  private fail(entry: Entry, error: unknown) {
    entry.state = 'failed'
    entry.failures++

    if (
      !(error instanceof OversizedFrameError) &&
      (!(error instanceof FrameHttpError) || error.retryable)
    )
      this.retry(entry)
    for (const owner of this.owners.values()) owner.notify()
  }
  private retry(entry: Entry) {
    const delay = Math.min(500 * 2 ** Math.min(entry.failures - 1, 6), 30_000)
    entry.retryTimer = setTimeout(() => {
      entry.retryTimer = undefined
      if (
        this.entries.get(entry.url) !== entry ||
        !this.desired().has(entry.url)
      )
        return
      entry.state = 'queued'

      this.reconcile()
    }, delay)
  }
}
let shared: FrameTransfer | undefined
export const getSharedFrameTransfer = () => (shared ??= new FrameTransfer())
